<h1 class="page-title">Lịch sử mua hàng</h1><div class="panel table-wrap"><table class="table"><thead><tr><th>Mã đơn</th><th>Ngày đặt</th><th>Tổng tiền</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><b><?= e($o['code']) ?></b></td><td><?= e($o['created_at']) ?></td><td><?= money($o['total']) ?></td><td><span class="status <?= e($o['status']) ?>"><?= e(status_label($o['status'])) ?></span></td><td><a href="/orders/<?= $o['id'] ?>" class="btn btn-light btn-sm">Xem chi tiết</a></td></tr><?php endforeach?></tbody></table><?php if(!$orders):?><p class="empty">Bạn chưa có đơn hàng.</p><?php endif?></div>
